window.CET6_LEARNING={collectBackup,validateBackup,validWorkspace,validLearning,dueItems,showReviewQueue,showLearningAnalysis,saveAudioPosition,get assetStats(){return{...assetStats}},get learning(){return learning},get queueSession(){return queueSession}};
